    'trigger home_layout.home_layout_guard O 107b0ec062f2c101fe1a83867d66dd26',
    'trigger machine_notes.machine_notes_guard O 01d467a0997dd9f9c631e150be7a61a4',
    'trigger meals.meals_guard O 8e74d57f7048ab2296f16bfd6b424af2',
    'trigger measurements.measurements_guard O 83edde0ef4246f082f8cc9b7dcaa28a8',
